const f = $('Document Q&A Form').item.json;
let ans = '';
const r = $json;
if (typeof r.content === 'string') ans = r.content;
else if (r.text) ans = r.text;
else if (r.response) ans = r.response;
else ans = JSON.stringify(r).slice(0, 1500);
return { email: f['Your email'], question: f.Question, answer: ans };

